/*
 * Which changed files a machine wrote. GitHub folds those by the same two
 * signals: the repository's `linguist-generated` attribute, and Linguist's
 * own list of well-known outputs. The attribute wins either way, so a
 * repository can unmark a file the list would catch.
 *
 * Only the root `.gitattributes` is read. A nested one is rare, and missing
 * it only leaves a file unfolded.
 */

/** Linguist's well-known generated files, by path. */
const GENERATED_PATHS: readonly RegExp[] = [
  // Lockfiles, each by its full name: `composer.json` is a hand-kept manifest.
  /(^|\/)(package-lock\.json|npm-shrinkwrap\.json|composer\.lock|Pipfile\.lock|flake\.lock)$/,
  /(^|\/)(yarn|Cargo|Gemfile|poetry|pdm|uv|Podfile|mix|pubspec)\.lock$/,
  /(^|\/)(pnpm-lock\.yaml|bun\.lockb?|go\.sum|Package\.resolved|gradle\.lockfile)$/,
  // Minified bundles and source maps.
  /\.min\.(js|css|mjs|cjs)$/,
  /\.(js|css|mjs|cjs)\.map$/,
  // Protocol buffers, gRPC, and other code generators.
  /\.pb\.(go|cc|h|swift|dart)$/,
  /_pb2(_grpc)?\.pyi?$/,
  /_(pb|grpc_pb|grpc_web_pb)\.(js|d\.ts|ts)$/,
  /(^|\/)__generated__\//,
  /\.(generated|gen)\.[a-z]+$/i,
  /\.g\.dart$/,
  /\.freezed\.dart$/,
  /\.designer\.(cs|vb)$/i,
  // Wrappers committed by build tools.
  /(^|\/)gradlew(\.bat)?$/,
  /(^|\/)gradle\/wrapper\//,
  /(^|\/)mvnw(\.cmd)?$/,
  /(^|\/)\.mvn\/wrapper\//,
];

/**
 * A generator's stamp, on a comment line of its own. A string in the
 * generator's own source that says the same is code, not a stamp.
 */
const GENERATED_HEADER =
  /^\s*(\/\/+|#+|\/\*+|\*+|<!--|--|;+|')\s*(.*\bCode generated\b.*\bDO NOT EDIT\b|@generated\b|<auto-generated\b|This file (is|was) (automatically|auto-) ?generated\b)/i;

/** How many of the new file's first lines the stamp is looked for in. */
const HEADER_LINES = 5;

/** One `.gitattributes` line that sets or clears `linguist-generated`. */
type GeneratedRule = { pattern: string; generated: boolean | null };

/**
 * The `linguist-generated` lines of a `.gitattributes`, in file order. A later
 * match overrides an earlier one, as in git. `null` is `!linguist-generated`,
 * which hands the file back to Linguist's list.
 */
export function parseGitattributes(text: string): GeneratedRule[] {
  const rules: GeneratedRule[] = [];
  for (const raw of text.split("\n")) {
    const line = raw.replace(/\r$/, "").trim();
    if (line === "" || line.startsWith("#")) continue;
    const [pattern, rest] = splitPattern(line);
    if (!pattern || pattern.startsWith("[attr]")) continue;
    for (const attribute of rest.split(/\s+/)) {
      const generated = generatedSetting(attribute);
      if (generated !== undefined) rules.push({ pattern, generated });
    }
  }
  return rules;
}

/** A line's pattern, unquoted when git quoted it, and the attributes after it. */
function splitPattern(line: string): [string, string] {
  if (!line.startsWith('"')) {
    const end = line.search(/\s/);
    return end === -1 ? [line, ""] : [line.slice(0, end), line.slice(end)];
  }
  let pattern = "";
  for (let index = 1; index < line.length; index++) {
    const char = line[index]!;
    if (char === '"') return [pattern, line.slice(index + 1)];
    if (char !== "\\") pattern += char;
    else {
      const next = line[++index] ?? "";
      pattern += next === "t" ? "\t" : next === "n" ? "\n" : next;
    }
  }
  // An unclosed quote: git ignores the line.
  return ["", ""];
}

/** What one attribute token says about `linguist-generated`, or undefined when it is another attribute. */
function generatedSetting(attribute: string): boolean | null | undefined {
  switch (attribute) {
    case "linguist-generated":
    case "linguist-generated=true":
      return true;
    case "-linguist-generated":
    case "linguist-generated=false":
      return false;
    case "!linguist-generated":
      return null;
    default:
      return undefined;
  }
}

/**
 * Whether a gitattributes pattern names `path`, by git's rules: a pattern
 * with no slash matches the file name at any depth, one with a slash
 * matches the whole path from the root. A pattern never matches the files
 * inside a directory it names, so a trailing slash matches no file.
 */
function attributeMatches(pattern: string, path: string): boolean {
  if (pattern.endsWith("/")) return false;
  if (!pattern.includes("/")) return globMatch(pattern, path.slice(path.lastIndexOf("/") + 1));
  return globMatch(pattern.replace(/^\//, ""), path);
}

/**
 * Git's wildmatch with a path: `*` and `?` stay within one directory, `**`
 * between slashes spans any number of them, and `[...]` is a character
 * class. Each pattern and path position is tried once, so no pattern can
 * stall the server the way a backtracking regex can.
 */
function globMatch(pattern: string, path: string): boolean {
  const memo = new Map<number, boolean>();
  const width = path.length + 1;

  const match = (p: number, s: number): boolean => {
    const key = p * width + s;
    let result = memo.get(key);
    if (result === undefined) {
      result = step(p, s);
      memo.set(key, result);
    }
    return result;
  };

  // `**/` is any number of whole directories, and a trailing `/**` is everything below.
  const anyDirectories = (p: number, s: number): boolean => {
    if (p + 2 === pattern.length) return true;
    for (let at = s; at <= path.length; at++) {
      const directoryStart = at === s || path[at - 1] === "/";
      if (directoryStart && match(p + 3, at)) return true;
    }
    return false;
  };

  // A lone `*`, or a `**` inside a name, stays within one directory.
  const withinDirectory = (next: number, s: number): boolean => {
    for (let at = s; at <= path.length; at++) {
      if (match(next, at)) return true;
      if (path[at] === "/") return false;
    }
    return false;
  };

  const star = (p: number, s: number): boolean => {
    if (pattern[p + 1] !== "*") return withinDirectory(p + 1, s);
    const ownSegment =
      (p === 0 || pattern[p - 1] === "/") && (p + 2 === pattern.length || pattern[p + 2] === "/");
    return ownSegment ? anyDirectories(p, s) : withinDirectory(p + 2, s);
  };

  const one = (p: number, s: number): boolean => {
    const char = pattern[p]!;
    const target = path[s]!;
    if (char === "?") return target !== "/" && match(p + 1, s + 1);
    const parsed = char === "[" ? characterClass(pattern, p) : null;
    if (parsed) return target !== "/" && parsed.test(target) && match(parsed.end, s + 1);
    const escaped = char === "\\" && p + 1 < pattern.length;
    if (escaped) return pattern[p + 1] === target && match(p + 2, s + 1);
    return char === target && match(p + 1, s + 1);
  };

  const step = (p: number, s: number): boolean => {
    if (p === pattern.length) return s === path.length;
    if (pattern[p] === "*") return star(p, s);
    return s < path.length && one(p, s);
  };

  return match(0, 0);
}

/** The `[...]` class opening at `start`, and where the pattern resumes after it. Null when it never closes. */
function characterClass(
  pattern: string,
  start: number,
): { test: (char: string) => boolean; end: number } | null {
  let index = start + 1;
  const negated = pattern[index] === "!" || pattern[index] === "^";
  if (negated) index++;
  const ranges: [string, string][] = [];
  let first = true;
  while (index < pattern.length && (first || pattern[index] !== "]")) {
    first = false;
    let low = pattern[index]!;
    if (low === "\\" && index + 1 < pattern.length) low = pattern[++index]!;
    if (
      pattern[index + 1] === "-" &&
      pattern[index + 2] !== undefined &&
      pattern[index + 2] !== "]"
    ) {
      ranges.push([low, pattern[index + 2]!]);
      index += 3;
    } else {
      ranges.push([low, low]);
      index++;
    }
  }
  if (pattern[index] !== "]") return null;
  return {
    test: (char) => ranges.some(([low, high]) => low <= char && char <= high) !== negated,
    end: index + 1,
  };
}

/** Whether the patch shows a generator's stamp in the new file's first lines. */
function hasGeneratedHeader(patch: string | null): boolean {
  const lines = patch?.split("\n") ?? [];
  // Only a first hunk that starts at the new file's line 1 shows its top.
  if (!/^@@ -\d+(,\d+)? \+1(,\d+)? @@/.test(lines[0] ?? "")) return false;
  let seen = 0;
  for (const line of lines.slice(1)) {
    if (line.startsWith("@@") || seen === HEADER_LINES) break;
    // A removed line is the old file's, not the new one's.
    if (line.startsWith("-") || line.startsWith("\\")) continue;
    seen++;
    if (GENERATED_HEADER.test(line.slice(1))) return true;
  }
  return false;
}

/** Whether a changed file is generated: by the repository's say first, then by Linguist's list or its header. */
export function isGenerated(
  path: string,
  patch: string | null,
  rules: readonly GeneratedRule[],
): boolean {
  let setting: boolean | null = null;
  for (const rule of rules) if (attributeMatches(rule.pattern, path)) setting = rule.generated;
  if (setting !== null) return setting;
  return GENERATED_PATHS.some((pattern) => pattern.test(path)) || hasGeneratedHeader(patch);
}
